-- Wire conformance bench (gh#273): the rows the CLIENT produces — fixtures/
-- wire_rows.json, generated byte-for-byte by DoneTests/
-- TelemetryWireConformanceTests.swift through the production store / center /
-- aggregators / TelemetryWire / TelemetryRedactor — are upserted into the real
-- public.spike_runs as an authenticated user exactly as PostgREST renders a
-- merge-duplicates upsert, then read back through the views. Every expected
-- value is taken from the JSON row itself (what the client sent is what the
-- server must hold), never retyped here.
-- Same conventions as telemetry_checks.sql: run from tests/ (cwd) inside the
-- db container over TCP (dblink needs scram); the fixture user is inserted
-- into auth.users and erased at the end (W9 is the cascade). Prints a
-- PASS/FAIL table and raises when any check failed (psql exits non-zero).
--   docker exec … psql -h <container ip> -U postgres -d postgres -v ON_ERROR_STOP=1 -f telemetry_wire_conformance.sql

\set QUIET on
\pset pager off
\set ON_ERROR_STOP on
\o /dev/null

create extension if not exists dblink;

create temp table bench (ord serial, id text, claim text, pass boolean, observed text);
create function pg_temp.rec(p_id text, p_claim text, p_pass boolean, p_observed text)
returns void language sql as $$
  insert into bench (id, claim, pass, observed) values (p_id, p_claim, coalesce(p_pass, false), p_observed);
$$;

select 'dbname=' || current_database() || ' user=postgres password=postgres host='
       || host(inet_server_addr()) || ' port=' || inet_server_port()::text as conninfo \gset
select gen_random_uuid() as w \gset

\if :{?wire_json}
\else
  \set wire_json `cat fixtures/wire_rows.json 2>/dev/null`
\endif

-- the fixture rows, in file order, with the client's placeholder user replaced
-- by the bench user (RLS with check: user_id = auth.uid())
create temp table wire (ord int, sent jsonb, run_id uuid, kind text, has_note boolean);
insert into wire
select ordinality, (value - 'user_id') || jsonb_build_object('user_id', :'w'::uuid), (value->>'run_id')::uuid, value->>'kind', value ? 'note'
from jsonb_array_elements(case when :'wire_json' = '' then '[]'::jsonb else :'wire_json'::jsonb end) with ordinality;
select count(*) as n_rows from wire \gset

delete from auth.users where email = 'tele-w@local.test';
insert into auth.users (id, email, aud, role, email_confirmed_at, raw_app_meta_data, raw_user_meta_data)
values (:'w', 'tele-w@local.test', 'authenticated', 'authenticated', now(), '{}', '{}');

create function pg_temp.as_user(conn text, uid uuid) returns void language plpgsql as $$
begin
  perform dblink_exec(conn, format('set request.jwt.claims = %L',
                                   format('{"sub":"%s","role":"authenticated"}', uid)));
  perform dblink_exec(conn, 'set role authenticated');
end $$;
create function pg_temp.try_exec(conn text, sql text) returns text language plpgsql as $$
begin
  return dblink_exec(conn, sql);
exception when others then
  return 'ERR:' || sqlstate;
end $$;

-- PostgREST's rendering of POST …?on_conflict=user_id,run_id with
-- Prefer: resolution=merge-duplicates: insert the columns the body carries
-- (jsonb_populate_record casts each to the table's type), on conflict set every
-- sent non-key column from excluded. A column the body omits (note, ended_at,
-- outcome) is left alone — exactly the "note key absent" semantics of wire §2.
create function pg_temp.wire_upsert_sql(row_json jsonb) returns text language sql as $$
  with cols as (select k from jsonb_object_keys(row_json) k order by k)
  select format($f$insert into public.spike_runs (%s) select %s from jsonb_populate_record(null::public.spike_runs, %L::jsonb)
                  on conflict (user_id, run_id) do update set %s$f$,
                (select string_agg(quote_ident(k), ', ') from cols),
                (select string_agg(quote_ident(k), ', ') from cols),
                row_json::text,
                (select string_agg(format('%1$I = excluded.%1$I', k), ', ') from cols where k not in ('user_id', 'run_id')))
$$;

select dblink_connect('W', :'conninfo');
select pg_temp.as_user('W', :'w');

-- ============================================================
-- W0  the fixture is present and shaped as the contract says
-- ============================================================
\echo '--- W0'
select count(*) filter (where kind = 'daily_rollup') as n_daily, count(*) filter (where kind = 'window') as n_window,
       count(*) filter (where kind = 'manual_run') as n_manual, count(*) filter (where kind = 'verdict_snapshot') as n_verdict,
       count(*) filter (where has_note) as n_note
from wire \gset
select pg_temp.rec('W0', 'fixtures/wire_rows.json loads: 6 rows — one daily_rollup, one window, three manual_run (one with a note key), one verdict_snapshot',
  :n_rows = 6 and :n_daily = 1 and :n_window = 1 and :n_manual = 3 and :n_verdict = 1 and :n_note = 1,
  format('rows=%s daily=%s window=%s manual=%s verdict=%s with note key=%s', :n_rows, :n_daily, :n_window, :n_manual, :n_verdict, :n_note));

-- ============================================================
-- W1  as W, every fixture row upserts (INSERT 0 1); the table holds N rows
-- ============================================================
\echo '--- W1'
create temp table tags1 as
select w.ord, w.run_id, pg_temp.try_exec('W', pg_temp.wire_upsert_sql(w.sent)) as tag from wire w order by w.ord;
select string_agg(ord || ':' || tag, ' ' order by ord) as tags1, count(*) filter (where tag <> 'INSERT 0 1') as bad1 from tags1 \gset
select count(*) as held1 from public.spike_runs where user_id = :'w' \gset
select pg_temp.rec('W1', 'as W, each of the client''s rows is accepted by the real table (every check constraint, type cast and RLS policy): N tags INSERT 0 1, N rows held',
  :bad1 = 0 and :held1 = :n_rows and :n_rows > 0, format('tags [%s]; rows held=%s of %s', :'tags1', :held1, :n_rows));

-- ============================================================
-- W2  the same batch again, same revisions -> every row skipped by the
--     guard (INSERT 0 0), row count unchanged, last_uploaded_at untouched
-- ============================================================
\echo '--- W2'
select string_agg(run_id || '=' || last_uploaded_at::text, ' ' order by run_id) as stamps_a from public.spike_runs where user_id = :'w' \gset
select pg_sleep(0.1);
create temp table tags2 as
select w.ord, pg_temp.try_exec('W', pg_temp.wire_upsert_sql(w.sent)) as tag from wire w order by w.ord;
select string_agg(ord || ':' || tag, ' ' order by ord) as tags2, count(*) filter (where tag <> 'INSERT 0 0') as bad2 from tags2 \gset
select count(*) as held2 from public.spike_runs where user_id = :'w' \gset
select string_agg(run_id || '=' || last_uploaded_at::text, ' ' order by run_id) as stamps_b from public.spike_runs where user_id = :'w' \gset
select pg_temp.rec('W2', 'the identical batch resent (same revision per row, as a client whose cursor was lost would do) is skipped row by row: N tags INSERT 0 0, still N rows, no last_uploaded_at moved',
  :bad2 = 0 and :held2 = :n_rows and :'stamps_a' = :'stamps_b',
  format('tags [%s]; rows=%s; stamps unchanged=%s', :'tags2', :held2, (:'stamps_a' = :'stamps_b')));

-- ============================================================
-- W3  stored == sent, column by column: the typed columns round-trip the
--     JSON values (date, smallint, integer, text, jsonb), timestamps to the
--     instant, and an absent note stays NULL
-- ============================================================
\echo '--- W3'
with cmp as (
  select w.ord,
         (jsonb_strip_nulls(to_jsonb(r)) - '{first_uploaded_at,last_uploaded_at,started_at,ended_at,client_updated_at}'::text[])
           = (w.sent - '{started_at,ended_at,client_updated_at}'::text[]) as plain_ok,
         (w.sent->>'started_at')::timestamptz = r.started_at as started_ok,
         ((w.sent ? 'ended_at') = (r.ended_at is not null)) and (not (w.sent ? 'ended_at') or (w.sent->>'ended_at')::timestamptz = r.ended_at) as ended_ok,
         (w.sent->>'client_updated_at')::timestamptz = r.client_updated_at as updated_ok,
         (w.sent ? 'note') = (r.note is not null) as note_ok,
         r.first_uploaded_at is not null and r.last_uploaded_at is not null as stamped_ok
  from wire w join public.spike_runs r on r.user_id = :'w' and r.run_id = w.run_id)
select count(*) as n3, count(*) filter (where plain_ok and started_ok and ended_ok and updated_ok and note_ok and stamped_ok) as ok3,
       coalesce(string_agg(ord || ':' || concat_ws(',', case when not plain_ok then 'columns' end, case when not started_ok then 'started_at' end,
                                           case when not ended_ok then 'ended_at' end, case when not updated_ok then 'client_updated_at' end,
                                           case when not note_ok then 'note' end, case when not stamped_ok then 'stamps' end), ' ')
                filter (where not (plain_ok and started_ok and ended_ok and updated_ok and note_ok and stamped_ok)), '') as bad3
from cmp \gset
select pg_temp.rec('W3', 'every stored row equals the row the client sent — every non-timestamp column as jsonb (metrics and context included), the three timestamps as instants, note NULL exactly where the key was absent — and the server stamped both upload times',
  :n3 = :n_rows and :ok3 = :n_rows, format('rows compared=%s equal=%s; mismatches [%s]', :n3, :ok3, :'bad3'));

-- ============================================================
-- W4  counter_long reads the daily row: every registered resident-daily
--     counter, with the values the client sent (release row, build in range)
-- ============================================================
\echo '--- W4'
select run_id as daily_run, sent->>'spike_id' as daily_spike, (sent->>'app_build')::int as daily_build, sent->>'day_key' as daily_day,
       sent->>'install_id' as daily_install, sent->'metrics' as daily_metrics from wire where kind = 'daily_rollup' \gset
select count(*) as cl_rows,
       count(*) filter (where value is null) as cl_nulls,
       count(*) filter (where value <> coalesce((:'daily_metrics'::jsonb->>key)::numeric, 0)) as cl_wrong
from public.counter_long where run_id = :'daily_run' \gset
select count(*) as cl_registered from public.key_registry where spike_id = :'daily_spike' and kind = 'counter' and value_schema = 'number'
  and since_build <= :daily_build and (retired_build is null or retired_build > :daily_build) \gset
select coalesce(max(value)::text, 'ABSENT') as cl_tap from public.counter_long where run_id = :'daily_run' and key = 'tapCount' \gset
select pg_temp.rec('W4', 'counter_long yields one line per registered resident-daily counter for the client''s daily row, none NULL (build in range), each equal to the metric the client sent (tapCount reads its sent value)',
  :cl_rows = :cl_registered and :cl_registered > 0 and :cl_nulls = 0 and :cl_wrong = 0 and :'cl_tap' = (:'daily_metrics'::jsonb->>'tapCount'),
  format('counter_long lines=%s registered counters=%s nulls=%s value mismatches=%s; tapCount=%s (sent %s)', :cl_rows, :cl_registered, :cl_nulls, :cl_wrong, :'cl_tap', :'daily_metrics'::jsonb->>'tapCount'));

-- ============================================================
-- W5  v_fixwatch_pooled_buckets parses the client's histogram string:
--     bucket i = the i-th space-separated integer of tapLagBuckets
-- ============================================================
\echo '--- W5'
select string_agg(bucket_idx || ':' || pooled_count, ' ' order by bucket_idx) as pooled, max(rows_pooled) as pooled_rows, count(*) as pooled_n
from public.v_fixwatch_pooled_buckets where app_build = :daily_build and key = 'tapLagBuckets' \gset
select string_agg((i - 1) || ':' || v, ' ' order by i) as expected_pooled, count(*) as expected_n
from unnest(string_to_array(:'daily_metrics'::jsonb->>'tapLagBuckets', ' ')) with ordinality as t(v, i) \gset
select pg_temp.rec('W5', 'the pooled-buckets view decodes the daily row''s tapLagBuckets into one line per bucket whose count is that bucket''s integer in the sent string, over exactly one pooled row',
  :pooled_n = :expected_n and :expected_n > 0 and :'pooled' = :'expected_pooled' and :pooled_rows = 1,
  format('view [%s] (rows_pooled=%s) vs sent "%s"', :'pooled', :pooled_rows, :'daily_metrics'::jsonb->>'tapLagBuckets'));

-- ============================================================
-- W6  v_fixwatch_verdicts_by_install expands the snapshot's metrics as sent
-- ============================================================
\echo '--- W6'
select sent->>'install_id' as verdict_install, sent->'metrics' as verdict_metrics from wire where kind = 'verdict_snapshot' \gset
select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) as verdict_view from public.v_fixwatch_verdicts_by_install where install_id = :'verdict_install' \gset
select pg_temp.rec('W6', 'the internal verdict view returns the snapshot row''s metrics key by key, values as sent (numbers and bools)',
  :'verdict_view'::jsonb = :'verdict_metrics'::jsonb and :'verdict_metrics'::jsonb <> '{}'::jsonb,
  format('view %s vs sent %s', :'verdict_view', :'verdict_metrics'));

-- ============================================================
-- W7  note lands only on the opt-in row — the row whose JSON had the key
-- ============================================================
\echo '--- W7'
select coalesce(string_agg(run_id::text, ','), '') as noted_rows from public.spike_runs where user_id = :'w' and note is not null \gset
select coalesce(string_agg(run_id::text, ','), '') as optin_rows from wire where has_note \gset
select pg_temp.rec('W7', 'exactly the fixture row that carried a note key has a non-null note on the server; the opt-out manual run and the legacy run have NULL',
  :'noted_rows' = :'optin_rows' and :'optin_rows' <> '', format('rows with note [%s]; rows sent with a note key [%s]', :'noted_rows', :'optin_rows'));

-- ============================================================
-- W8  the window row: number_list / bool metrics are not counters; the
--     window's counters are read; v_active_installs counts the daily install
-- ============================================================
\echo '--- W8'
select run_id as window_run, sent->'metrics' as window_metrics from wire where kind = 'window' \gset
select count(*) filter (where key in ('wCommitMs', 'wLagMs', 'wFrameAfterCommitMs', 'wContaminated', 'wTruncatedGesture', 'wClosedByResign')) as cl_nonnum,
       coalesce(max(value) filter (where key = 'wTaps'), -1) as cl_wtaps,
       coalesce(max(value) filter (where key = 'wWritingTaps'), -1) as cl_wwriting
from public.counter_long where run_id = :'window_run' \gset
select coalesce(max(active_installs), 0) as active from public.v_active_installs where day_key = :'daily_day'::date and app_build = :daily_build \gset
select pg_temp.rec('W8', 'counter_long never casts the window''s number_list or bool metrics, reads wTaps and wWritingTaps as sent; v_active_installs counts the daily row''s install on its day and build',
  :cl_nonnum = 0 and :cl_wtaps = (:'window_metrics'::jsonb->>'wTaps')::numeric and :cl_wwriting = (:'window_metrics'::jsonb->>'wWritingTaps')::numeric and :active = 1,
  format('non-numeric keys in counter_long=%s; wTaps=%s (sent %s) wWritingTaps=%s (sent %s); active_installs=%s', :cl_nonnum, :cl_wtaps, :'window_metrics'::jsonb->>'wTaps', :cl_wwriting, :'window_metrics'::jsonb->>'wWritingTaps', :active));

-- ============================================================
-- W9  cleanup through the cascade
-- ============================================================
\echo '--- W9'
select dblink_disconnect('W');
select count(*) as rows0 from public.spike_runs where user_id = :'w' \gset
delete from auth.users where id = :'w';
select count(*) as rows1 from public.spike_runs where user_id = :'w' \gset
select pg_temp.rec('W9', 'deleting the fixture user cascades every uploaded row away',
  :rows0 = :n_rows and :rows1 = 0, format('rows %s -> %s', :rows0, :rows1));

\o
\echo
\echo '=== results'
\pset format aligned
select case when pass then 'PASS' else 'FAIL' end as verdict, id, claim, observed from bench order by ord;
select count(*) filter (where not pass) as fails, count(*) filter (where not pass) > 0 as any_fail from bench \gset
\if :any_fail
  \echo 'FAILED checks:' :fails
  do $$ begin raise exception 'telemetry_wire_conformance: some checks failed'; end $$;
\else
  \echo 'all wire conformance checks passed'
\endif
